+    store.active.pop(workspace_id, None)
def cleanup_setup(store, workspace_id, setup_id):
    store.pending.pop(setup_id, None)
    store.active.pop(workspace_id, None)
def begin_setup(store, workspace_id, setup_id):
    store.pending[setup_id] = {"workspace_id": workspace_id}


def complete_setup(store, workspace_id, setup_id, connection):
    store.active[workspace_id] = {"setup_id": setup_id, "connection": connection}
    store.pending.pop(setup_id, None)


def active_connection(store, workspace_id):
    association = store.active.get(workspace_id)
    return association["connection"] if association else None
class Store:
    def __init__(self):
        self.pending = {}
        self.active = {}
import unittest
from store import Store
from setup import begin_setup, complete_setup, active_connection
from cleanup import cleanup_setup


class SetupTests(unittest.TestCase):
    def test_completed_setup_is_visible(self):
        store = Store()
        begin_setup(store, "w", "one")
        complete_setup(store, "w", "one", "connection-one")
        self.assertEqual(active_connection(store, "w"), "connection-one")

    def test_cleanup_removes_its_own_association(self):
        store = Store()
        begin_setup(store, "w", "one")
        complete_setup(store, "w", "one", "connection-one")
        cleanup_setup(store, "w", "one")
        self.assertIsNone(active_connection(store, "w"))
        self.assertNotIn("one", store.pending)

